-- READ-ONLY. Run on the target DB: lists Prisma-expected columns of the driver-onboarding tables that do not exist there.
-- Empty result = no schema drift on these tables.
SELECT e.t AS table_name, e.c AS missing_column FROM (SELECT 'tbl_rider' t, c FROM (SELECT 'id' c UNION ALL SELECT 'first_name' c UNION ALL SELECT 'last_name' c UNION ALL SELECT 'full_name' c UNION ALL SELECT 'email' c UNION ALL SELECT 'account_name' c UNION ALL SELECT 'account_number' c UNION ALL SELECT 'ifsc' c UNION ALL SELECT 'verification_type' c UNION ALL SELECT 'verification_status' c UNION ALL SELECT 'trial_status' c UNION ALL SELECT 'trial_orders_allowed' c UNION ALL SELECT 'trial_orders_completed' c UNION ALL SELECT 'body_type' c UNION ALL SELECT 'fmobile' c UNION ALL SELECT 'smobile' c UNION ALL SELECT 'nationality' c UNION ALL SELECT 'dob' c UNION ALL SELECT 'city_id' c UNION ALL SELECT 'full_address' c UNION ALL SELECT 'know_language' c UNION ALL SELECT 'profile_picture' c UNION ALL SELECT 'survey_status' c UNION ALL SELECT 'status' c UNION ALL SELECT 'a_status' c UNION ALL SELECT 'block_reason' c UNION ALL SELECT 'rlats' c UNION ALL SELECT 'rlongs' c UNION ALL SELECT 'rloc_updated_at' c UNION ALL SELECT 'all_verify' c UNION ALL SELECT 'rdate' c UNION ALL SELECT 'add_info' c UNION ALL SELECT 'update_by' c UNION ALL SELECT 'password' c UNION ALL SELECT 'fcm_token' c UNION ALL SELECT 'vehicle' c UNION ALL SELECT 'driver_basic_type' c UNION ALL SELECT 'wallet_balance' c UNION ALL SELECT 'plan_type' c UNION ALL SELECT 'monthly_plan' c UNION ALL SELECT 'working_hours' c UNION ALL SELECT 'vehicle_no' c UNION ALL SELECT 'upi_id' c UNION ALL SELECT 'device_id' c UNION ALL SELECT 'reffer_code' c UNION ALL SELECT 'refferal_code' c UNION ALL SELECT 'refer_by' c UNION ALL SELECT 'wallet_points' c UNION ALL SELECT 'referral_code' c UNION ALL SELECT 'referred_by' c UNION ALL SELECT 'referred_by_type' c UNION ALL SELECT 'referral_points' c UNION ALL SELECT 'payment_complete' c UNION ALL SELECT 'model1_miss_streak' c UNION ALL SELECT 'model1_suspended_until' c UNION ALL SELECT 'training_completed_at' c UNION ALL SELECT 'training_progress' c) x UNION ALL SELECT 'tbl_personal_doc' t, c FROM (SELECT 'id' c UNION ALL SELECT 'rider_id' c UNION ALL SELECT 'is_bycle' c UNION ALL SELECT 'residence_status' c UNION ALL SELECT 'residence_id' c UNION ALL SELECT 'residence_front' c UNION ALL SELECT 'residence_back' c UNION ALL SELECT 'address_status' c UNION ALL SELECT 'address_id' c UNION ALL SELECT 'address_front' c UNION ALL SELECT 'address_back' c UNION ALL SELECT 'lic_status' c UNION ALL SELECT 'lic_id' c UNION ALL SELECT 'lic_front' c UNION ALL SELECT 'lic_back' c UNION ALL SELECT 'status' c UNION ALL SELECT 'pan_status' c UNION ALL SELECT 'pan_id' c UNION ALL SELECT 'pan_front' c UNION ALL SELECT 'pan_back' c UNION ALL SELECT 'aadhar_status' c UNION ALL SELECT 'aadhar_id' c UNION ALL SELECT 'aadhar_front' c UNION ALL SELECT 'aadhar_back' c UNION ALL SELECT 'aadhaar_back' c UNION ALL SELECT 'upi_image' c UNION ALL SELECT 'puc_image' c UNION ALL SELECT 'bima_image' c UNION ALL SELECT 'rc_owner_name' c UNION ALL SELECT 'rc_owner_aadhar_number' c) x UNION ALL SELECT 'tbl_vehicle_details' t, c FROM (SELECT 'id' c UNION ALL SELECT 'rider_id' c UNION ALL SELECT 'type_id' c UNION ALL SELECT 'reg_num' c UNION ALL SELECT 'v_pic' c UNION ALL SELECT 'status' c UNION ALL SELECT 'rejection_reason' c UNION ALL SELECT 'name_mismatch' c) x UNION ALL SELECT 'tbl_bank_account' t, c FROM (SELECT 'id' c UNION ALL SELECT 'rider_id' c UNION ALL SELECT 'iban_num' c UNION ALL SELECT 'ifsc_code' c UNION ALL SELECT 'bank_name' c UNION ALL SELECT 'branch_name' c UNION ALL SELECT 'a_name' c UNION ALL SELECT 'vat_id' c UNION ALL SELECT 'status' c) x UNION ALL SELECT 'tbl_rider_delivery_type' t, c FROM (SELECT 'id' c UNION ALL SELECT 'rider_id' c UNION ALL SELECT 'delivery_type' c UNION ALL SELECT 'status' c) x UNION ALL SELECT 'pkg_category' t, c FROM (SELECT 'cat_img' c UNION ALL SELECT 'other_image' c UNION ALL SELECT 'id' c UNION ALL SELECT 'cat_status' c UNION ALL SELECT 'cat_name' c UNION ALL SELECT 'city_id' c UNION ALL SELECT 'sort_order' c UNION ALL SELECT 'max_load_kg' c UNION ALL SELECT 'dim_length' c UNION ALL SELECT 'dim_width' c UNION ALL SELECT 'dim_height' c UNION ALL SELECT 'dim_unit' c UNION ALL SELECT 'detail_image' c UNION ALL SELECT 'allowed_body_types' c UNION ALL SELECT 'driver_body_types' c UNION ALL SELECT 'max_extra_stops' c UNION ALL SELECT 'extra_stop_charge' c) x UNION ALL SELECT 'tbl_package' t, c FROM (SELECT 'id' c UNION ALL SELECT 'title' c UNION ALL SELECT 'user_title' c UNION ALL SELECT 'driver_title' c UNION ALL SELECT 'driver_card_subtitle' c UNION ALL SELECT 'driver_info_subtitle' c UNION ALL SELECT 'driver_info_sections' c UNION ALL SELECT 'type' c UNION ALL SELECT 'min_charge' c UNION ALL SELECT 'per_km_charge' c UNION ALL SELECT 'driver_per_trip' c UNION ALL SELECT 'driver_per_percent' c UNION ALL SELECT 'free_waiting_time' c UNION ALL SELECT 'waiting_charge' c UNION ALL SELECT 'service_charge_percent' c UNION ALL SELECT 'night_charge_percent' c UNION ALL SELECT 'start_time' c UNION ALL SELECT 'end_time' c UNION ALL SELECT 'cat_id' c UNION ALL SELECT 'city_id' c UNION ALL SELECT 'user_detail_image' c UNION ALL SELECT 'driver_detail_image' c UNION ALL SELECT 'loading_charge' c UNION ALL SELECT 'unloading_charge' c UNION ALL SELECT 'service_charge' c UNION ALL SELECT 'pickup_charge' c UNION ALL SELECT 'status' c UNION ALL SELECT 'premium_plan_id' c UNION ALL SELECT 'sort_order' c UNION ALL SELECT 'pickup_per_km_charge' c UNION ALL SELECT 'outside_min_charge' c UNION ALL SELECT 'outside_per_km_charge' c UNION ALL SELECT 'outside_surcharge' c UNION ALL SELECT 'cancellation_charge_customer' c UNION ALL SELECT 'cancellation_charge_driver' c UNION ALL SELECT 'admin_earning' c UNION ALL SELECT 'driver_earning' c UNION ALL SELECT 'no_driver_compensation' c UNION ALL SELECT 'driver_cancel_admin_earning' c UNION ALL SELECT 'driver_cancel_user_earning' c UNION ALL SELECT 'cancellation_charge' c UNION ALL SELECT 'use_linear_pricing' c) x) e LEFT JOIN information_schema.columns i ON i.table_schema=DATABASE() AND i.table_name=e.t AND i.column_name=e.c WHERE i.column_name IS NULL;
